    val missing: Set<String> = setOf(

    )

    private val byKey: Map<String, StickerEntry> = entries.associateBy { it.key }

    fun entry(key: String): StickerEntry? = byKey[key]

    @DrawableRes
    fun drawable(key: String): Int? = byKey[key]?.drawable

    fun isBundled(key: String): Boolean = key in byKey
